using Order = std::tuple<std::string, int, int>;  // (side, price, qty)

int total_fills(const std::vector<Order>& orders) {
    std::priority_queue<std::pair<int,int>> buys;          // max-heap
    std::priority_queue<std::pair<int,int>,
                        std::vector<std::pair<int,int>>,
                        std::greater<>> sells;             // min-heap
    int total = 0;

    for (auto& [side, price, qty] : orders) {
        int remaining = qty;
        if (side == "BUY") {
            while (remaining > 0 && !sells.empty() && sells.top().first <= price) {
                auto [sell_price, sell_qty] = sells.top();
                sells.pop();
                int filled = std::min(remaining, sell_qty);
                total += filled;
                remaining -= filled;
                if (sell_qty > filled)
                    sells.push({sell_price, sell_qty - filled});
            }
            if (remaining > 0)
                buys.push({price, remaining});
        } else {
            // SELL: the mirror image, against buys.top()
        }
    }
    return total;
}

struct Trade { int aggressorId, restingId, price, qty; };

class Orderbook {
public:
    void AddOrder(int orderId, bool isBuy, int price, int qty) {
        if (active_.count(orderId)) return;              // reject duplicate
        active_.insert(orderId);
        int remaining = qty;
        if (isBuy) matchBuy(orderId, price, remaining);
        else       matchSell(orderId, price, remaining);
        if (remaining > 0) {
            if (isBuy) bids_[price].push_back({orderId, remaining});
            else       asks_[price].push_back({orderId, remaining});
        } else {
            active_.erase(orderId);                      // fully filled
        }
    }

private:
    struct Entry { int orderId, qty; };
    std::map<int, std::deque<Entry>, std::greater<int>> bids_;  // begin() = best bid
    std::map<int, std::deque<Entry>>                    asks_;  // begin() = best ask
    std::unordered_set<int> active_, cancelled_;
    std::vector<Trade> trades_;

    void matchBuy(int aggressorId, int aggressorPrice, int& remaining) {
        while (remaining > 0 && !asks_.empty()) {
            auto it = asks_.begin();
            if (it->first > aggressorPrice) break;      // best ask doesn't cross
            skipCancelled(it->second);
            if (it->second.empty()) { asks_.erase(it); continue; }

            auto& resting = it->second.front();          // oldest at this price
            int filled = std::min(remaining, resting.qty);
            trades_.push_back({aggressorId, resting.orderId, it->first, filled});
            remaining   -= filled;
            resting.qty -= filled;
            if (resting.qty == 0) {
                active_.erase(resting.orderId);
                it->second.pop_front();
                if (it->second.empty()) asks_.erase(it);
            }
        }
    }
};

void CancelOrder(int orderId) {
    if (!active_.count(orderId)) return;
    active_.erase(orderId);
    cancelled_.insert(orderId);       // O(1): leave the deque alone
}

void skipCancelled(std::deque<Entry>& dq) {
    while (!dq.empty() && cancelled_.count(dq.front().orderId)) {
        cancelled_.erase(dq.front().orderId);
        dq.pop_front();               // tombstone popped on access
    }
}
